/**
 * Worker entry point: reuses the fetch handler generated by OpenNext and adds
 * a scheduled handler for Cron Triggers (evening push reminders).
 * See https://opennext.js.org/cloudflare/howtos/custom-worker
 */
// The file only exists after `opennextjs-cloudflare build`, so the error is not always present.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore `.open-next/worker.js` is generated at build time.
import { default as handler } from "../.open-next/worker.js";

interface ReminderEnv {
  BETTER_AUTH_URL: string;
  CRON_SECRET?: string;
}

const worker = {
  fetch: handler.fetch,

  /** Calls the protected reminder route through the app itself. */
  async scheduled(_controller: unknown, env: ReminderEnv, ctx: { waitUntil(promise: Promise<unknown>): void }) {
    if (!env.CRON_SECRET) {
      return;
    }
    const request = new Request(new URL("/api/cron/reminders", env.BETTER_AUTH_URL), {
      method: "POST",
      headers: { Authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(handler.fetch(request, env, ctx));
  },
};

export default worker;
